import{_ as o,o as t,c as a,ae as s}from"./chunks/framework.B3uLoxsb.js";const m=JSON.parse('{"title":"Source: docs/COMPATIBILITY.md","description":"","frontmatter":{},"headers":[],"relativePath":"zh/reference/source/compatibility.md","filePath":"zh/reference/source/compatibility.md","lastUpdated":1771052491000}'),i={name:"zh/reference/source/compatibility.md"};function l(c,e,r,p,d,n){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="source-docs-compatibility-md" tabindex="-1">Source: docs/COMPATIBILITY.md <a class="header-anchor" href="#source-docs-compatibility-md" aria-label="Permalink to &quot;Source: docs/COMPATIBILITY.md&quot;">​</a></h1><h1 id="compatibility-operations" tabindex="-1">Compatibility Operations <a class="header-anchor" href="#compatibility-operations" aria-label="Permalink to &quot;Compatibility Operations&quot;">​</a></h1><p>This project maintains a full Antigravity-compatible <code>.agent</code> tree in two places:</p><ul><li><code>skills/codex-workflows/packs/antigravity-compat/.agent</code></li><li><code>skills/codex-workflows/templates/.agent</code></li></ul><p>The first is the compatibility pack and the second is the compatibility baseline template.</p><p>Default project bootstrap now uses:</p><ul><li><code>skills/codex-workflows/templates/codex-native/.agent</code> as independent source</li><li>includes native <code>agents/</code> and <code>skills/</code> catalogs separate from compatibility content</li><li>includes layered codex-native rules (<code>global</code>, <code>domains</code>, <code>workflows</code>)</li></ul><p>Compatibility content is only used when <code>--profile antigravity-compat</code> is explicitly selected.</p><h2 id="source-of-truth" tabindex="-1">Source of truth <a class="header-anchor" href="#source-of-truth" aria-label="Permalink to &quot;Source of truth&quot;">​</a></h2><p>Use a local Antigravity <code>.agent</code> snapshot as input source.</p><p>For day-to-day repository maintenance, you can rebuild a valid compatibility manifest by using:</p><p><code>python skills/codex-workflows/scripts/codex_workflows_ops.py build-manifest</code></p><p>This command uses <code>./.agent</code> if present in the current working directory and otherwise falls back to <code>packs/antigravity-compat/.agent</code>.</p><h2 id="sync-process" tabindex="-1">Sync process <a class="header-anchor" href="#sync-process" aria-label="Permalink to &quot;Sync process&quot;">​</a></h2><ol><li><p>Sync pack from source: <code>python skills/codex-workflows/scripts/sync_compat_pack.py --source &lt;path-to-.agent&gt;</code></p></li><li><p>Copy updated pack to full template: <code>Copy-Item -Recurse -Force skills/codex-workflows/packs/antigravity-compat/.agent/* skills/codex-workflows/templates/.agent</code></p></li><li><p>Rebuild manifest: <code>python skills/codex-workflows/scripts/build_compat_manifest.py --source &lt;path-to-.agent&gt; --pack skills/codex-workflows/packs/antigravity-compat/.agent --template-full skills/codex-workflows/templates/.agent --output skills/codex-workflows/compat/manifest.json</code></p></li><li><p>Validate drift: <code>python skills/codex-workflows/scripts/check_compat_drift.py --manifest skills/codex-workflows/compat/manifest.json --pack skills/codex-workflows/packs/antigravity-compat/.agent --template-full skills/codex-workflows/templates/.agent</code></p></li><li><p>Validate workflow parity: <code>python skills/codex-workflows/scripts/check_workflow_parity.py --references skills/codex-workflows/references/workflows --native skills/codex-workflows/templates/codex-native/.agent/workflows --template skills/codex-workflows/templates/.agent/workflows --pack skills/codex-workflows/packs/antigravity-compat/.agent/workflows</code></p></li></ol><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li><code>.pyc</code> and <code>__pycache__</code> files are intentionally excluded from manifests.</li><li>Compatibility checks should pass locally before opening a release PR.</li><li><code>references/workflows</code> is part of the codex-native track, not the compatibility source of truth.</li></ul>',17)])])}const k=o(i,[["render",l]]);export{m as __pageData,k as default};
